css:
.print-format-builder {
    font-size: 14px;
    font-family: 'Times New Roman', Times, serif;
    line-height: 1.5;
    color: #000;
    padding: 10px;
}

.header-table {
    width: 100%;
    border-bottom: 2px solid #5a5a5a;
    padding-bottom: 10px;
    margin-bottom: 30px;
}

.header-text {
    font-size: 11px;
    line-height: 1.4;
}

.ref-date-section, .address-section {
    margin-bottom: 20px;
}

.subject-line {
    text-align: center;
    font-weight: bold;
    font-size: 15px;
    margin-bottom: 20px;
}

.body-paragraph {
    text-align: justify;
    margin-bottom: 15px;
}

.terms-list {
    text-align: justify;
    padding-left: 22px;
}

.terms-list > li {
    margin-bottom: 10px;
}

.sub-list {
    list-style-type: lower-alpha;
    padding-left: 20px;
    margin-top: 6px;
}

.sub-list li {
    margin-bottom: 4px;
}

.highlight-yellow {
    background-color: yellow;
}

.page-break {
    page-break-before: always;
}

.annexure-header-box {
    text-align: right;
    margin-bottom: 10px;
}

.annexure-title {
    text-align: center;
    font-weight: bold;
    font-size: 15px;
    margin-bottom: 15px;
}

.annexure-table, .annexure-notes-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-bottom: 20px;
}

.annexure-table th, .annexure-table td, 
.annexure-notes-table td {
    border: 1px solid #000;
    padding: 6px 10px;
}

.bold { font-weight: bold; }
.text-center { text-align: center; }
.text-right { text-align: right; }

.annexure-footer-notes {
    font-size: 14px;
    margin-top: 30px;
}
.annexure-footer-notes ol {
    padding-left: 25px;
    margin-bottom: 40px;
}
.annexure-footer-notes li {
    margin-bottom: 8px;
}
.signatory-block {
    margin-bottom: 40px;
}
.signature-space {
    margin-top: 60px;
}

.print-format-builder {
    font-family: "Arial", sans-serif;
    font-size: 15px;
    color: #000;
    line-height: 1.6;
    padding: 20px 40px;
}

/* Page Break for Annexure */
.page-break {
    page-break-before: always;
}

/* Letter Styles */
.letter-header {
    border-bottom: 2px solid #000;
    padding-bottom: 15px;
    margin-bottom: 40px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.header-text {
    font-size: 9.5px;
    line-height: 1.3;
}

.header-text strong {
    font-size: 11px;
}

.header-logo img {
    max-width: 200px;
    height: auto;
}

.date-section {
    margin-bottom: 30px;
}

.address-section {
    margin-bottom: 40px;
    line-height: 1.5;
}

.subject-line {
    margin-bottom: 30px;
}

.salutation {
    margin-bottom: 20px;
}

.body-paragraph {
    margin-bottom: 20px;
    text-align: justify;
}

.signatory-section {
    margin-top: 30px;
    line-height: 1.5;
}

.bold {
    font-weight: bold;
}

/* Annexure Table Styles */
.annexure-header {
    text-align: right;
    margin-bottom: 20px;
}
.annexure-header img {
    max-width: 180px;
}
.annexure-title {
    text-align: center;
    font-weight: bold;
    font-size: 16px;
    margin-bottom: 20px;
    line-height: 1.4;
}

.annexure-table, .terms-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
}

/* Yahan terms-table td hta diya hai border line se */
.annexure-table th, .annexure-table td {
    border: 1px solid #000;
    padding: 6px 10px;
}

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.terms-table {
    margin-top: 20px;
}

/* Terms table ke liye specific no-border property */
.terms-table td {
    border: none !important;
    padding: 6px 10px;
    vertical-align: top;
}

.list-num {
